use std::{
    any::TypeId,
    collections::{HashMap, hash_map::Entry},
};

use hashbrown::{HashSet, hash_set};

use crate::Reflection;

/// Collection of [`Reflection`] types.
#[derive(Debug)]
pub(crate) struct TypeMap {
    /// Registered types for documentation.
    ///
    /// The keys are generated by [`Reflection::type_name`].
    name_map: HashMap<String, Reflection>,

    /// The type IDs present in `name_map`.
    type_ids: HashSet<TypeId>,
}

impl TypeMap {
    /// Create a new empty type-map.
    pub(crate) fn new() -> Self {
        Self {
            name_map: HashMap::new(),
            type_ids: HashSet::new(),
        }
    }

    /// Return the [`Reflection`] type information for the provided type-name.
    pub(crate) fn type_info(&self, type_name: &str) -> Option<Reflection> {
        self.name_map.get(type_name).copied()
    }

    /// Return an iterator over all the registered type-names.
    pub(crate) fn type_names(&self) -> impl ExactSizeIterator<Item = &str> {
        self.name_map.keys().map(|v| &**v)
    }

    pub(crate) fn register(
        &mut self,
        reflections: &[Reflection],
    ) -> Result<Transaction<'_>, Conflict> {
        let mut t = Transaction::new(self);

        reflections.iter().try_for_each(|r| {
            r.visit_with(|r: Reflection| -> Result<bool, Conflict> {
                let type_id = r.type_id();

                // If the type doesn't exist - try to add it via type-name.
                // Only if all that succeeds to we commit the type-id.
                if let hash_set::Entry::Vacant(vacant_type_id) = t.map.type_ids.entry(type_id) {
                    let type_name = r.type_name().to_string();
                    match t.map.name_map.entry(type_name) {
                        // Everything checks out, we're good to go.
                        Entry::Vacant(vacant_type_name) => {
                            vacant_type_name.insert(r);
                            vacant_type_id.insert();
                            t.added.push(type_id);
                        }
                        Entry::Occupied(occupied_type_name) => {
                            // This branch is only reachable if `type_id` did not exist
                            // in `type_ids`, which means it never could have entered into
                            // `name_map` anyways.
                            debug_assert_ne!(occupied_type_name.get().type_id(), type_id);

                            return Err(Conflict {
                                type_name: occupied_type_name.key().clone(),
                            });
                        }
                    }

                    // Continue exploring.
                    Ok(true)
                } else {
                    // Already seen this node. No need to recurse.
                    Ok(false)
                }
            })
        })?;

        Ok(t)
    }
}

#[derive(Debug)]
pub(crate) struct Conflict {
    type_name: String,
}

impl std::fmt::Display for Conflict {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(
            f,
            "A different type with the type name \"{}\" was already registered",
            self.type_name
        )
    }
}

impl std::error::Error for Conflict {}

#[derive(Debug)]
#[must_use = "transactions must be explicitly completed - otherwise they automatically abort"]
pub(crate) struct Transaction<'a> {
    map: &'a mut TypeMap,
    added: Vec<TypeId>,
}

impl<'a> Transaction<'a> {
    fn new(map: &'a mut TypeMap) -> Self {
        Self {
            map,
            added: Vec::new(),
        }
    }

    fn roll_back(&mut self) {
        // Nothing to roll back.
        if self.added.is_empty() {
            return;
        }

        // We first roll-back the type IDs that were added, which is relatively easy.
        // Then, we cannot rely on `Reflect::type_name` returning the same name every time.
        // So instead, we have to loop over all entries in `name_map` and inspect the
        // `TypeId`s directly (which we control) to determing removal.
        //
        // Fortunately, `extract_if` does exactly what we want.
        let mut added_type_ids = HashSet::new();
        for type_id in std::mem::take(&mut self.added) {
            self.map.type_ids.remove(&type_id);
            added_type_ids.insert(type_id);
        }

        self.map
            .name_map
            .retain(|_, v| !added_type_ids.contains(&v.type_id()));
    }

    pub(crate) fn complete(mut self) {
        self.added.clear();
    }
}

impl Drop for Transaction<'_> {
    fn drop(&mut self) {
        self.roll_back()
    }
}

///////////
// Tests //
///////////

#[cfg(test)]
mod tests {
    use super::*;

    use crate::Reflect;

    // The types `A`, `B`, `C`, etc. are the valid types for testing registration.

    #[derive(Reflect)]
    #[expect(unused, reason = "testing")]
    struct A {
        a: usize,
        b: Option<String>,
    }

    #[derive(Reflect)]
    #[expect(unused, reason = "testing")]
    struct B(A, f32);

    #[derive(Reflect)]
    #[expect(unused, reason = "testing")]
    struct C {
        a: f64,
        b: isize,
    }

    #[derive(Reflect)]
    #[expect(unused, reason = "testing")]
    enum D {
        V0(A),
        V1 { first: B, second: B },
        V2,
        V3(Vec<Option<C>>),
    }

    // The type tree `Bad0`, `Bad1`, etc. are the types we use to test the erroring path.
    //
    // The idea is that somewhere at the bottom of this path is a type with a type-name
    // that conflicts with one of the "good" types above.
    #[derive(Reflect)]
    #[reflect(type_name = "usize")]
    struct Bad0;

    #[derive(Reflect)]
    #[expect(unused, reason = "testing")]
    struct Bad1 {
        a: usize,
        b: D,
        c: i32,
        d: Option<Bad0>,
    }

    #[derive(Reflect)]
    #[expect(unused, reason = "testing")]
    struct Bad2(u32, Vec<Bad1>);

    #[derive(Reflect)]
    #[expect(unused, reason = "testing")]
    enum Bad3 {
        Unit,
        S(String),
        B { field: Bad2 },
    }

    fn register<T>(map: &mut TypeMap) -> Result<Transaction<'_>, Conflict>
    where
        T: Reflect,
    {
        map.register(&[Reflection::new::<T>()])
    }

    fn type_name_for<T>() -> String
    where
        T: Reflect,
    {
        Reflection::new::<T>().type_name().to_string()
    }

    fn assert_is_present<T>(map: &TypeMap)
    where
        T: Reflect,
    {
        let type_name = type_name_for::<T>();
        let r = map.type_info(&type_name).unwrap();

        assert_eq!(r.type_id(), TypeId::of::<T>());
        assert_eq!(r.type_name().to_string(), type_name);
    }

    fn assert_is_absent<T>(map: &TypeMap)
    where
        T: Reflect,
    {
        let type_name = type_name_for::<T>();
        if let Some(r) = map.type_info(&type_name) {
            assert_ne!(
                r.type_id(),
                Reflection::new::<T>().type_id(),
                "Did not expect \"{}\" to be registered",
                std::any::type_name::<T>(),
            );
        }
    }

    // We expect the following types to be present.
    //
    // * usize
    // * String
    // * Option<String>
    // * f32
    // * f64
    // * isize
    // * A
    // * B
    // * C
    // * Option<C>
    // * Vec<Option<C>>
    // * D
    //
    // The following types should *not* be present.
    //
    // * i32
    // * Bad0
    // * Option<Bad0>
    // * Bad1
    // * u32
    // * Vec<Bad1>
    // * Bad2
    // * Bad3
    fn check_types_are_present(r: &TypeMap) {
        assert_is_present::<usize>(r);
        assert_is_present::<String>(r);
        assert_is_present::<Option<String>>(r);
        assert_is_present::<f32>(r);
        assert_is_present::<f64>(r);
        assert_is_present::<isize>(r);
        assert_is_present::<A>(r);
        assert_is_present::<B>(r);
        assert_is_present::<C>(r);
        assert_is_present::<Option<C>>(r);
        assert_is_present::<Vec<Option<C>>>(r);
        assert_is_present::<D>(r);

        assert_is_absent::<i32>(r);
        assert_is_absent::<Bad0>(r);
        assert_is_absent::<Option<Bad0>>(r);
        assert_is_absent::<Bad1>(r);
        assert_is_absent::<u32>(r);
        assert_is_absent::<Vec<Bad1>>(r);
        assert_is_absent::<Bad2>(r);
        assert_is_absent::<Bad3>(r);
    }

    // Register the entire type-tree at once.
    #[test]
    fn test_registration_all() {
        let mut map = TypeMap::new();
        register::<D>(&mut map).unwrap().complete();
        check_types_are_present(&map);

        // Registering again should be fine.
        register::<D>(&mut map).unwrap().complete();
        check_types_are_present(&map);
    }

    // Multiple total types can be registered in one call.
    #[test]
    fn test_register_multiple() {
        let mut map = TypeMap::new();
        map.register(&[Reflection::new::<usize>(), Reflection::new::<f32>()])
            .unwrap()
            .complete();

        assert_is_present::<usize>(&map);
        assert_is_present::<f32>(&map);
    }

    // Roll-back undoes multiple types.
    #[test]
    fn test_multiple_roll_back() {
        let mut map = TypeMap::new();

        // Drop aborts the transaction
        let _ = map
            .register(&[Reflection::new::<usize>(), Reflection::new::<f32>()])
            .unwrap();

        assert!(map.name_map.is_empty());
        assert!(map.type_ids.is_empty());
    }

    // Register portions of the type-tree.
    #[test]
    fn test_incremental_registration() {
        let mut map = TypeMap::new();
        register::<String>(&mut map).unwrap().complete();
        register::<usize>(&mut map).unwrap().complete();
        register::<B>(&mut map).unwrap().complete();
        register::<D>(&mut map).unwrap().complete();

        check_types_are_present(&map);

        register::<B>(&mut map).unwrap().complete();
        check_types_are_present(&map);
    }

    // Immediate errors do not leave invalid state in the map.
    #[test]
    fn test_errors_are_recoverable() {
        let mut map = TypeMap::new();

        // Registering the "bad" type should eventually hit a naming conflict.
        // Everything should be rolled back and adding the "good" type should still work.
        let err = register::<Bad3>(&mut map).unwrap_err();
        let msg = err.to_string();
        assert_eq!(
            msg,
            "A different type with the type name \"usize\" was already registered"
        );

        assert!(
            map.name_map.is_empty(),
            "invalid registration should not commit registered items"
        );

        assert!(
            map.type_ids.is_empty(),
            "invalid registration should not commit registered items"
        );

        let err = map
            .register(&[Reflection::new::<usize>(), Reflection::new::<Bad3>()])
            .unwrap_err();
        assert_eq!(err.to_string(), msg);
        assert!(map.name_map.is_empty());
        assert!(map.type_ids.is_empty());

        // After this, we should succeed in adding more types correctly.
        register::<D>(&mut map).unwrap().complete();
        check_types_are_present(&map);

        // Again, bad registration should not corrupt the map.
        register::<Bad3>(&mut map).unwrap_err();
        check_types_are_present(&map);
    }
}
